// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceDriveProgress {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // This creates 1-element array, since this seems to be the only way to construct a const
    // pointer that we can pass to the Rust code.
    static let vtable: [UniffiVTableCallbackInterfaceDriveProgress] = [UniffiVTableCallbackInterfaceDriveProgress(
        onProgress: { (
            uniffiHandle: UInt64,
            label: RustBuffer,
            fraction: RustBuffer,
            uniffiOutReturn: UnsafeMutableRawPointer,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> () in
                guard let uniffiObj = try? FfiConverterTypeDriveProgress.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.onProgress(
                     label: try FfiConverterString.lift(label),
                     fraction: try FfiConverterOptionDouble.lift(fraction)
                )
            }

            
            let writeReturn = { () }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        },
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            let result = try? FfiConverterTypeDriveProgress.handleMap.remove(handle: uniffiHandle)
            if result == nil {
                print("Uniffi callback interface DriveProgress: handle missing in uniffiFree")
            }
        }
    )]
}

