#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeImpalaCore: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = ImpalaCore

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> ImpalaCore {
        return ImpalaCore(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: ImpalaCore) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

