         */heftImages: [String], 
        /**
         * Seiten, deren offene Ansicht schließen (Papierkorb, Archiv, endgültig gelöscht).
         */closedPages: [String]) {
        self.everything = everything
        self.remote = remote
        self.pages = pages
        self.pagesAll = pagesAll
        self.pagesMeta = pagesMeta
        self.cards = cards
        self.cardsAll = cardsAll
        self.chats = chats
        self.chatsAll = chatsAll
        self.decks = decks
        self.reviews = reviews
        self.grades = grades
        self.learningSessions = learningSessions
        self.homeArticles = homeArticles
        self.settings = settings
        self.workspaces = workspaces
        self.heftFolders = heftFolders
        self.ui = ui
