        /**
         * Neu übernommene Events.
         */imported: UInt64, 
        /**
         * Hochgeladene eigene Events.
         */uploaded: UInt64, 
        /**
         * Konflikte (Konfliktkopien angelegt) beim Übernehmen.
         */conflicts: UInt64, 
        /**
         * Automatisch zusammengeführte Seiten.
         */merged: UInt64, filesDownloaded: UInt64, filesUploaded: UInt64, 
        /**
         * Sync-Stand in Drive wurde zu einem Snapshot verdichtet.
         */compacted: Bool, 
        /**
         * Fremde Änderungen wurden geholt (Sync-Modus, erster Durchgang, Wiederherstellen).
         */pulled: Bool, 
        /**
         * Geräteuhr weicht so weit von Drive ab, dass gewarnt werden soll (Minuten).
         */clockWarningMinutes: UInt64?, 
        /**
         * „Synchronisiert“ oder „Aktuell“.
         */label: String) {
        self.imported = imported
        self.uploaded = uploaded
        self.conflicts = conflicts
        self.merged = merged
        self.filesDownloaded = filesDownloaded
