public enum AiFailure: Swift.Error {

    
    
    /**
     * Es läuft schon eine Anfrage dieses Assistenten.
     */
    case Busy
    /**
     * Mit `cancel` (oder durch Abbruch einer Rückfrage) beendet.
     */
    case Aborted
    case Timeout(reason: String
    )
    case Network(reason: String
    )
    case Http(status: UInt16, reason: String, retryAfterMs: UInt64
    )
    /**
     * Fehlende Einrichtung, unbrauchbare Antwort, Speicherfehler.
     */
    case Other(reason: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAiFailure: FfiConverterRustBuffer {
    typealias SwiftType = AiFailure

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AiFailure {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Busy
        case 2: return .Aborted
        case 3: return .Timeout(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Network(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Http(
            status: try FfiConverterUInt16.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf), 
            retryAfterMs: try FfiConverterUInt64.read(from: &buf)
            )
        case 6: return .Other(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AiFailure, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .Busy:
            writeInt(&buf, Int32(1))
        
        
        case .Aborted:
            writeInt(&buf, Int32(2))
        
        
        case let .Timeout(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Network(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Http(status,reason,retryAfterMs):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(status, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            FfiConverterUInt64.write(retryAfterMs, into: &buf)
            
        
        case let .Other(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAiFailure_lift(_ buf: RustBuffer) throws -> AiFailure {
    return try FfiConverterTypeAiFailure.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeAiFailure_lower(_ value: AiFailure) -> RustBuffer {
    return FfiConverterTypeAiFailure.lower(value)
}


