    case removeStrokes(page: String, ids: [String]
    )
    case addImage(page: String, image: HeftImage
    )
    case setImage(page: String, image: HeftImage
    )
    case removeImages(page: String, ids: [String]
    )
    case addText(page: String, text: HeftText
    )
    case setText(page: String, text: HeftText
    )
    case removeTexts(page: String, ids: [String]
    )
    /**
     * Neue Seite `page` an Position `at` (`None`: hinten).
     */
    case addPage(at: UInt32?, page: String, paper: String?
    )
    case removePage(page: String
    )
    /**
     * Neue Reihenfolge aller Seiten-IDs.
     */
    case setPageOrder(order: [String]
    )
