        )
        
        case 5: return .setImage(page: try FfiConverterString.read(from: &buf), image: try FfiConverterTypeHeftImage.read(from: &buf)
        )
        
        case 6: return .removeImages(page: try FfiConverterString.read(from: &buf), ids: try FfiConverterSequenceString.read(from: &buf)
        )
        
