        )
        
        case 8: return .setText(page: try FfiConverterString.read(from: &buf), text: try FfiConverterTypeHeftText.read(from: &buf)
        )
        
        case 9: return .removeTexts(page: try FfiConverterString.read(from: &buf), ids: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 10: return .addPage(at: try FfiConverterOptionUInt32.read(from: &buf), page: try FfiConverterString.read(from: &buf), paper: try FfiConverterOptionString.read(from: &buf)
        )
        
        case 11: return .removePage(page: try FfiConverterString.read(from: &buf)
        )
        
        case 12: return .setPageOrder(order: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 13: return .setPaper(page: try FfiConverterString.read(from: &buf), paper: try FfiConverterString.read(from: &buf)
        )
        
        case 14: return .setPageText(page: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HeftChange, into buf: inout [UInt8]) {
        switch value {
        
        
