            FfiConverterString.write(page, into: &buf)
            FfiConverterTypeHeftImage.write(image, into: &buf)
            
        
        case let .removeImages(page,ids):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(page, into: &buf)
            FfiConverterSequenceString.write(ids, into: &buf)
            
        
        case let .addText(page,text):
