            writeInt(&buf, Int32(10))
            FfiConverterOptionUInt32.write(at, into: &buf)
            FfiConverterString.write(page, into: &buf)
            FfiConverterOptionString.write(paper, into: &buf)
            
        
        case let .removePage(page):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(page, into: &buf)
            
        
        case let .setPageOrder(order):
            writeInt(&buf, Int32(12))
            FfiConverterSequenceString.write(order, into: &buf)
            
        
        case let .setPaper(page,paper):
