        case .divider:
            writeInt(&buf, Int32(5))
        
        
        case let .image(alt,src):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(alt, into: &buf)
            FfiConverterString.write(src, into: &buf)
            
        
        case let .heft(heftId):
